const demoKey='orbitflow-crm-demo-v1';
const seed={
 leads:[{id:'L-1001',name:'Aster & Co.',contact:'Maya Shah',value:120000,stage:'New',note:'Brand identity enquiry'},{id:'L-1002',name:'Nexon Studio',contact:'Rohan Mehta',value:185000,stage:'Qualified',note:'Website redesign project'},{id:'L-1003',name:'Casa Botanica',contact:'Nina Thomas',value:240000,stage:'Proposal',note:'Creative retainer proposal'},{id:'L-1004',name:'Blue Shore Hotels',contact:'Arjun Kapoor',value:310000,stage:'Negotiation',note:'Campaign planning'}],
 clients:[{id:'C-201',name:'Aster & Co.',contact:'Maya Shah',value:120000,status:'Active'},{id:'C-202',name:'Casa Botanica',contact:'Nina Thomas',value:240000,status:'Active'},{id:'C-203',name:'Blue Shore Hotels',contact:'Arjun Kapoor',value:310000,status:'Active'}],
 projects:[{id:'P-301',name:'Brand refresh',client:'Aster & Co.',progress:68,status:'In progress'},{id:'P-302',name:'Website redesign',client:'Nexon Studio',progress:44,status:'In progress'},{id:'P-303',name:'Campaign launch',client:'Blue Shore Hotels',progress:82,status:'In progress'}],
 invoices:[{id:'INV-1042',client:'Aster & Co.',amount:82000,status:'Outstanding',due:'Today'},{id:'INV-1043',client:'Blue Shore Hotels',amount:125000,status:'Outstanding',due:'24 Sep'},{id:'INV-1039',client:'Casa Botanica',amount:240000,status:'Paid',due:'Paid'}],
 events:[{id:'E-401',title:'Discovery call',time:'10:30',date:'Today'},{id:'E-402',title:'Proposal review',time:'14:00',date:'Today'},{id:'E-403',title:'Client onboarding',time:'11:00',date:'Tomorrow'}]
};
let store;try{store=JSON.parse(localStorage.getItem(demoKey))||structuredClone(seed)}catch{store=structuredClone(seed)}
let activeView='Dashboard';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const toast=$('#toast'),dashboard=$('.content'),view=$('#demoView');
const currency=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function save(){localStorage.setItem(demoKey,JSON.stringify(store))}
function showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2300)}
function openModal(type='Lead',record=null){
 const fields={Lead:[['Company name','name'],['Contact person','contact'],['Deal value (INR)','value','number'],['Stage','stage','select','New|Qualified|Proposal|Negotiation']],Client:[['Client name','name'],['Contact person','contact'],['Lifetime value (INR)','value','number']],Project:[['Project name','name'],['Client','client'],['Progress %','progress','number']],Invoice:[['Client','client'],['Amount (INR)','amount','number'],['Due date','due']],Event:[['Event title','title'],['Time','time'],['Date','date']]};
 const typeKey=type==='Calendar'?'Event':type;
 const existing=record||{};$('#demoModal').innerHTML=`<form class="modal-card" id="recordForm"><div class="modal-head"><div><p class="eyebrow">DEMO DATA</p><h2>${record?'Edit':'Create'} ${esc(typeKey)}</h2></div><button type="button" class="close-modal">×</button></div><div class="form-fields">${fields[typeKey].map(([label,key,input='text',options=''])=>`<label>${label}${input==='select'?`<select name="${key}">${options.split('|').map(v=>`<option ${existing[key]===v?'selected':''}>${v}</option>`).join('')}</select>`:`<input name="${key}" type="${input}" required value="${esc(existing[key]??'')}">`}</label>`).join('')}</div><div class="modal-actions"><button type="button" class="outline close-modal">Cancel</button><button class="new-button">Save ${esc(typeKey)}</button></div></form>`;$('#demoModal').showModal();$$('.close-modal').forEach(b=>b.onclick=()=>$('#demoModal').close());$('#recordForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(typeKey==='Lead'){data.id=record?.id||`L-${Date.now().toString().slice(-5)}`;data.value=Number(data.value);data.note=record?.note||'New opportunity';record?Object.assign(record,data):store.leads.unshift(data)}if(typeKey==='Client'){data.id=record?.id||`C-${Date.now().toString().slice(-5)}`;data.value=Number(data.value);data.status='Active';record?Object.assign(record,data):store.clients.unshift(data)}if(typeKey==='Project'){data.id=record?.id||`P-${Date.now().toString().slice(-5)}`;data.progress=Number(data.progress);data.status='In progress';record?Object.assign(record,data):store.projects.unshift(data)}if(typeKey==='Invoice'){data.id=record?.id||`INV-${Date.now().toString().slice(-4)}`;data.amount=Number(data.amount);data.status=record?.status||'Outstanding';record?Object.assign(record,data):store.invoices.unshift(data)}if(typeKey==='Event'){data.id=record?.id||`E-${Date.now().toString().slice(-4)}`;record?Object.assign(record,data):store.events.unshift(data)}save();$('#demoModal').close();render(activeView);showToast(`${typeKey} saved in your demo`)}}
function openDetail(type,id){const map={Lead:'leads',Client:'clients',Project:'projects',Invoice:'invoices',Event:'events'};const record=store[map[type]].find(r=>r.id===id);if(!record)return;const summary=Object.entries(record).filter(([k])=>!['id','status','stage'].includes(k)).map(([k,v])=>`<div><span>${k.replace(/\b\w/g,x=>x.toUpperCase())}</span><b>${esc(k==='value'||k==='amount'?currency(v):v)}</b></div>`).join('');const action=type==='Lead'?'<button class="new-button" id="advanceRecord">Advance stage</button>':type==='Invoice'&&record.status!=='Paid'?'<button class="new-button" id="advanceRecord">Mark paid</button>':'';$('#detailDrawer').innerHTML=`<div class="drawer-card"><button class="drawer-close">×</button><p class="eyebrow">${esc(type)} RECORD</p><h2>${esc(record.name||record.client||record.title)}</h2><span class="status-pill">${esc(record.stage||record.status||record.date)}</span><div class="detail-grid">${summary}</div><div class="drawer-actions"><button class="outline" id="editRecord">Edit</button>${action}</div></div>`;$('#detailDrawer').showModal();$('.drawer-close').onclick=()=>$('#detailDrawer').close();$('#editRecord').onclick=()=>{ $('#detailDrawer').close();openModal(type,record)};const advance=$('#advanceRecord');if(advance)advance.onclick=()=>{if(type==='Lead'){const stages=['New','Qualified','Proposal','Negotiation','Won'];record.stage=stages[Math.min(stages.indexOf(record.stage)+1,stages.length-1)]}else record.status='Paid';save();$('#detailDrawer').close();render(activeView);showToast('Record updated')}}
function recordCard(type,record,secondary){return `<button class="demo-record" data-type="${type}" data-id="${record.id}"><span class="record-mark">${type==='Invoice'?'₹':type==='Event'?'◷':'◉'}</span><span>${esc(record.name||record.client||record.title)}<small>${esc(secondary)}</small></span><b>›</b></button>`}
function renderView(){const configs={Leads:{eyebrow:'LEAD MANAGEMENT',title:'Lead workspace',text:'Qualify new opportunities and turn conversations into clients.',type:'Lead',data:'leads',group:r=>r.stage},Pipeline:{eyebrow:'OPPORTUNITY MANAGEMENT',title:'Pipeline command center',text:'Move every opportunity from enquiry to signed agreement.',type:'Lead',data:'leads',group:r=>r.stage},Clients:{eyebrow:'CLIENT RELATIONSHIPS',title:'Client 360°',text:'Every conversation, document and payment in one client record.',type:'Client',data:'clients',group:r=>r.status},Projects:{eyebrow:'DELIVERY WORKSPACE',title:'Projects at a glance',text:'Keep delivery, approvals and budgets on track.',type:'Project',data:'projects',group:r=>r.status},Invoices:{eyebrow:'FINANCE OVERVIEW',title:'Invoices and payments',text:'Know what is paid, pending and due next.',type:'Invoice',data:'invoices',group:r=>r.status},Calendar:{eyebrow:'SCHEDULE',title:'Your week, in focus',text:'Meetings, follow-ups and delivery dates in one calendar.',type:'Event',data:'events',group:r=>r.date}};if(activeView==='Dashboard'){dashboard.hidden=false;view.hidden=true;return}dashboard.hidden=true;view.hidden=false;const c=configs[activeView],rows=store[c.data],groups=[...new Set(rows.map(c.group))];view.innerHTML=`<div class="demo-hero"><div><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p>${c.text}</p></div><button class="light demo-action" id="createFromView">＋ Add ${c.type}</button></div><div class="demo-columns">${groups.map((group,index)=>`<article class="demo-column"><div class="column-head"><h2>${esc(group)}</h2><span>${String(rows.filter(r=>c.group(r)===group).length).padStart(2,'0')}</span></div>${rows.filter(r=>c.group(r)===group).map(r=>recordCard(c.type,r,c.type==='Lead'?`${r.contact} · ${currency(r.value)}`:c.type==='Invoice'?`${currency(r.amount)} · ${r.due}`:c.type==='Project'?`${r.client} · ${r.progress}% complete`:c.type==='Event'?`${r.time} · ${r.date}`:`${r.contact} · ${currency(r.value)}`)).join('')}</article>`).join('')}</div><section class="panel demo-insight"><div><p class="eyebrow">AI INSIGHT</p><h2>Ready for the next conversation</h2><p>OrbitFlow highlights priority actions and keeps the full customer context close to hand.</p></div><button class="text-button" id="resetDemo">Reset demo data</button></section>`;$('#createFromView').onclick=()=>openModal(c.type);$('#resetDemo').onclick=()=>{store=structuredClone(seed);save();render(activeView);showToast('Demo data reset')};$$('.demo-record').forEach(b=>b.onclick=()=>openDetail(b.dataset.type,b.dataset.id))}
function render(name){activeView=name;$('#crumb').textContent=name;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));renderView()}
function renderSearch(query){if(!query.trim()){render(activeView);return}dashboard.hidden=true;view.hidden=false;const all=[...store.leads.map(x=>({type:'Lead',r:x,text:`${x.name} ${x.contact}`})),...store.clients.map(x=>({type:'Client',r:x,text:`${x.name} ${x.contact}`})),...store.projects.map(x=>({type:'Project',r:x,text:`${x.name} ${x.client}`})),...store.invoices.map(x=>({type:'Invoice',r:x,text:`${x.client} ${x.id}`}))].filter(x=>x.text.toLowerCase().includes(query.toLowerCase()));view.innerHTML=`<div class="search-results"><p class="eyebrow">GLOBAL SEARCH</p><h1>Results for “${esc(query)}”</h1><p>${all.length} records found in the demo workspace.</p><div class="panel result-list">${all.map(x=>recordCard(x.type,x.r,`${x.type} · ${x.r.id}`)).join('')||'<p class="empty">No records found. Try another client or document name.</p>'}</div></div>`;$$('.demo-record').forEach(b=>b.onclick=()=>openDetail(b.dataset.type,b.dataset.id))}
$('#newButton').onclick=()=>openModal('Lead');$('#addLead').onclick=()=>openModal('Lead');$('.outline').onclick=()=>render('Pipeline');$$('.nav-item').forEach(b=>b.onclick=()=>render(b.dataset.view));$('.search input').addEventListener('input',e=>renderSearch(e.target.value));$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');
document.body.insertAdjacentHTML('beforeend','<dialog id="demoModal"></dialog><dialog id="detailDrawer"></dialog>');renderView();

const topMenu=document.getElementById('topMenu');if(topMenu)topMenu.onclick=()=>document.getElementById('sidebar').classList.toggle('open');
